def evaluate_circuit_breaker_transition(state: str, failure_count: int, failure_threshold: int, last_failure_time: float, current_time: float, recovery_timeout: float, call_succeeded: bool) -> tuple[str, int, float]:
    """Transitions circuit breaker state between CLOSED, OPEN, and HALF_OPEN based on failures, timeout, and call outcome.
    Returns (new_state, new_failure_count, new_last_failure_time).
    """
    valid_states = {"CLOSED", "OPEN", "HALF_OPEN"}
    if state not in valid_states:
        raise ValueError(f"Invalid state: {state}")

    # Check recovery timeout for OPEN state
    if state == "OPEN":
        if (current_time - last_failure_time) >= recovery_timeout:
            state = "HALF_OPEN"
        else:
            return ("OPEN", failure_count, last_failure_time)

    if state == "HALF_OPEN":
        if call_succeeded:
            return ("CLOSED", 0, last_failure_time)
        else:
            return ("OPEN", failure_count + 1, current_time)

    # State is CLOSED
    if call_succeeded:
        return ("CLOSED", 0, last_failure_time)
    else:
        new_count = failure_count + 1
        if new_count >= failure_threshold:
            return ("OPEN", new_count, current_time)
        else:
            return ("CLOSED", new_count, current_time)
